arguments.new:
module bump_one() {
    // Detent: low cam ridge on the slot floor at 80 deg. The lug clears it
    // by 0.15 in CAD pose; in use the lug rides on the slot floor, so the
    // ridge cams the lid up 0.45 and drops it back just before lock.
    translate([34.0*cos(80), 34.0*sin(80), 68.625])
        cylinder(h=0.45, r=0.9, center=true);
}
